/// Stress capacity (SU/RPM) of Create generators.
pub mod capacity {
    pub const CREATIVE_MOTOR: f32 = 16384.0;
    pub const WATER_WHEEL: f32 = 32.0;
    pub const LARGE_WATER_WHEEL: f32 = 128.0;
    pub const HAND_CRANK: f32 = 8.0;
    pub const COPPER_VALVE_HANDLE: f32 = 8.0;
    /// Per engine; Create scales it by boiler efficiency.
    pub const STEAM_ENGINE: f32 = 1024.0;
    pub const WINDMILL_BEARING: f32 = 512.0;
}

/// Consumer role for a machine with the given impact.
pub fn machine(impact: f32) -> NodeRole {
    NodeRole::Consumer { impact }
}

/// Creative motor at `rpm` (Create default 16, range ±maxRotationSpeed).
pub fn creative_motor(rpm: f32) -> NodeRole {
    NodeRole::Source {
        rpm,
        capacity: capacity::CREATIVE_MOTOR,
    }
}

/// Hand crank being turned (32 RPM; negative when cranked the other way).
pub fn hand_crank(backwards: bool) -> NodeRole {
    NodeRole::Source {
        rpm: if backwards { -32.0 } else { 32.0 },
        capacity: capacity::HAND_CRANK,
    }
}

/// Water wheel: `flow` in -1..=1 (Create's clamped flow score). Large wheels turn at
/// half speed (`8 / size`).
pub fn water_wheel(flow: f32, large: bool) -> NodeRole {
    let (size, cap) = if large {
        (2.0, capacity::LARGE_WATER_WHEEL)
    } else {
        (1.0, capacity::WATER_WHEEL)
    };
    NodeRole::Source {
        rpm: flow.clamp(-1.0, 1.0) * 8.0 / size,
        capacity: cap,
    }
}

/// Steam engine shaft: 16 RPM × `speed_modifier` (boiler level), capacity scaled by
/// `efficiency` (0..=1), like `PoweredShaftBlockEntity`.
pub fn steam_engine(speed_modifier: f32, efficiency: f32) -> NodeRole {
    let cap = capacity::STEAM_ENGINE * efficiency;
    let rpm = if cap > 0.0 {
        16.0 * speed_modifier
    } else {
        0.0
    };
    NodeRole::Source { rpm, capacity: cap }
}

#[cfg(test)]
mod tests {
    use super::super::network::{Network, Status};
    use super::*;

    #[test]
    fn hand_crank_runs_one_press_at_32_rpm() {
        // 8 SU/RPM * 32 RPM = 256 SU; press 8 SU/RPM * 32 RPM = 256 SU
        let mut n = Network::new();
        let c = n.add_node(hand_crank(false));
        let p = n.add_node(machine(impact::MECHANICAL_PRESS));
        n.connect(c, p, 1.0);
        let s = n.solve();
        assert_eq!(s.status_of(c), &Status::Running);
        assert_eq!(s.subnetworks[0].capacity, 256.0);
    }

    #[test]
    fn large_water_wheel_is_slower_but_stronger() {
        match water_wheel(1.0, true) {
            NodeRole::Source { rpm, capacity } => assert_eq!(rpm * capacity, 512.0),
            _ => unreachable!(),
        }
        match water_wheel(1.0, false) {
            NodeRole::Source { rpm, capacity } => assert_eq!(rpm * capacity, 256.0),
            _ => unreachable!(),
        }
    }
}
